/* Reset e base */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.custom-table-wrapper {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
  width: 100%;
  height: 100%;
  background: linear-gradient(45deg, #ff6b6b, #4ecdc4, #45b7d1, #96ceb4, #ffeaa7, #fd79a8, #fdcb6e, #6c5ce7, #a29bfe, #fd79a8);
  background-size: 400% 400%;
  animation: psychedelicBackground 8s ease infinite;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
}

@keyframes psychedelicBackground {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Header */
.header-info {
  background: linear-gradient(45deg, #ff0066, #ff6600, #ffcc00, #66ff00, #00ff66, #00ffcc, #0066ff, #6600ff, #cc00ff, #ff0066);
  background-size: 1000% 1000%;
  animation: rainbowHeader 3s ease infinite;
  color: white;
  padding: clamp(1rem, 3vw, 1.5rem) clamp(1rem, 4vw, 2rem);
  border-radius: 20px;
  margin: clamp(0.5rem, 2vw, 1rem);
  margin-bottom: clamp(0.5rem, 1vw, 0.75rem);
  box-shadow: 0 0 30px rgba(255, 0, 255, 0.7), 0 0 60px rgba(0, 255, 255, 0.5);
  flex-shrink: 0;
  z-index: 100;
  border: 3px solid transparent;
  background-clip: padding-box;
  position: relative;
  overflow: hidden;
}

@keyframes rainbowHeader {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.header-info::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(45deg, #ff0066, #ff6600, #ffcc00, #66ff00, #00ff66, #00ffcc, #0066ff, #6600ff, #cc00ff, #ff0066);
  background-size: 1000% 1000%;
  animation: rainbowBorder 2s ease infinite;
  z-index: -1;
  border-radius: 20px;
  padding: 3px;
}

@keyframes rainbowBorder {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.header-title {
  font-size: clamp(1rem, 3vw, 1.5rem);
  font-weight: 700;
  line-height: 1.4;
  text-align: center;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.8), 0 0 20px rgba(255, 0, 255, 0.6), 0 0 30px rgba(0, 255, 255, 0.4);
  word-wrap: break-word;
  hyphens: auto;
  animation: textGlow 2s ease infinite alternate;
}

@keyframes textGlow {
  0% { text-shadow: 0 0 10px rgba(255, 255, 255, 0.8), 0 0 20px rgba(255, 0, 255, 0.6), 0 0 30px rgba(0, 255, 255, 0.4); }
  100% { text-shadow: 0 0 20px rgba(255, 255, 255, 1), 0 0 30px rgba(255, 0, 255, 0.8), 0 0 40px rgba(0, 255, 255, 0.6); }
}

.header-title .highlight {
  background: linear-gradient(45deg, #ff0066, #00ffcc, #ffcc00, #66ff00);
  background-size: 400% 400%;
  animation: highlightMove 1.5s ease infinite;
  padding: 0.2rem 0.5rem;
  border-radius: 10px;
  font-weight: 800;
  margin: 0 0.2rem;
  display: inline-block;
  box-shadow: 0 0 15px rgba(255, 255, 255, 0.5);
}

@keyframes highlightMove {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Indicatore di progresso */
.progress-indicator {
  background: linear-gradient(45deg, #ff6b6b, #4ecdc4, #45b7d1, #96ceb4, #ffeaa7, #fd79a8);
  background-size: 600% 600%;
  animation: progressRainbow 4s ease infinite;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 2rem);
  margin: 0 clamp(0.5rem, 2vw, 1rem) clamp(0.5rem, 1vw, 0.75rem);
  border-radius: 15px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: clamp(0.5rem, 2vw, 1rem);
  box-shadow: 0 0 25px rgba(255, 0, 255, 0.4), 0 0 50px rgba(0, 255, 255, 0.3);
  border: 2px solid rgba(255, 255, 255, 0.3);
  font-size: clamp(0.8rem, 2vw, 0.95rem);
  font-weight: 600;
  flex-shrink: 0;
  color: white;
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
}

@keyframes progressRainbow {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.progress-indicator span {
  white-space: nowrap;
  text-align: center;
  min-width: 0;
  animation: textPulse 2s ease infinite alternate;
}

@keyframes textPulse {
  0% { transform: scale(1); }
  100% { transform: scale(1.05); }
}

.validation-summary {
  background: linear-gradient(45deg, #ff0066, #ff6600, #ffcc00);
  background-size: 300% 300%;
  animation: errorPulse 1s ease infinite;
  color: white;
  font-weight: 700;
  padding: 0.5rem 1rem;
  border-radius: 10px;
  border: 2px solid rgba(255, 255, 255, 0.5);
  text-align: center;
  width: 100%;
  box-shadow: 0 0 20px rgba(255, 0, 0, 0.6);
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.7);
}

@keyframes errorPulse {
  0% { background-position: 0% 50%; box-shadow: 0 0 20px rgba(255, 0, 0, 0.6); }
  50% { background-position: 100% 50%; box-shadow: 0 0 30px rgba(255, 0, 0, 0.8); }
  100% { background-position: 0% 50%; box-shadow: 0 0 20px rgba(255, 0, 0, 0.6); }
}

/* Contenitore tabella */
.table-container {
  flex: 1;
  margin: 0 clamp(0.5rem, 2vw, 1rem);
  background: linear-gradient(45deg, rgba(255, 255, 255, 0.9), rgba(255, 255, 255, 0.95));
  border-radius: 15px;
  overflow: auto;
  box-shadow: 0 0 40px rgba(255, 0, 255, 0.3), 0 0 80px rgba(0, 255, 255, 0.2);
  border: 3px solid transparent;
  background-clip: padding-box;
  min-height: 0;
  position: relative;
}

.table-container::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(45deg, #ff0066, #ff6600, #ffcc00, #66ff00, #00ff66, #00ffcc, #0066ff, #6600ff, #cc00ff, #ff0066);
  background-size: 1000% 1000%;
  animation: tableBorder 5s ease infinite;
  z-index: -1;
  border-radius: 15px;
  padding: 3px;
}

@keyframes tableBorder {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Tabella */
.detail-table {
  width: 100%;
  border-collapse: collapse;
  font-size: clamp(0.8rem, 2vw, 0.95rem);
  table-layout: fixed;
  position: relative;
}

.detail-table th {
  background: linear-gradient(45deg, #ff6b6b, #4ecdc4, #45b7d1, #96ceb4);
  background-size: 400% 400%;
  animation: headerCells 3s ease infinite;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 1.5rem);
  text-align: left;
  font-weight: 700;
  color: white;
  border-bottom: 3px solid rgba(255, 255, 255, 0.3);
  width: clamp(120px, 30%, 200px);
  vertical-align: middle;
  position: relative;
  word-wrap: break-word;
  hyphens: auto;
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
}

@keyframes headerCells {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.detail-table td {
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 1.5rem);
  border-bottom: 2px solid rgba(255, 0, 255, 0.2);
  vertical-align: middle;
  word-wrap: break-word;
  overflow-wrap: break-word;
  position: relative;
  background: rgba(255, 255, 255, 0.8);
  transition: all 0.3s ease;
}

.detail-table tr:hover td {
  background: linear-gradient(45deg, rgba(255, 107, 107, 0.2), rgba(78, 205, 196, 0.2), rgba(69, 183, 209, 0.2));
  background-size: 400% 400%;
  animation: rowHover 2s ease infinite;
  transform: scale(1.02);
  box-shadow: 0 0 20px rgba(255, 0, 255, 0.3);
}

@keyframes rowHover {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.detail-table tr.error-row td {
  background: linear-gradient(45deg, rgba(255, 0, 102, 0.3), rgba(255, 102, 0, 0.3));
  background-size: 400% 400%;
  animation: errorRow 1.5s ease infinite;
  border-left: 5px solid #ff0066;
  box-shadow: 0 0 15px rgba(255, 0, 102, 0.4);
}

@keyframes errorRow {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.detail-table tr.error-row th {
  background: linear-gradient(45deg, #ff0066, #ff6600);
  background-size: 400% 400%;
  animation: errorHeader 1.5s ease infinite;
  color: white;
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.7);
}

@keyframes errorHeader {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

/* Indicatore campo obbligatorio */
.required-indicator {
  color: #ff0066;
  font-weight: bold;
  margin-left: 0.3rem;
  font-size: 1.2rem;
  animation: requiredPulse 1s ease infinite;
  text-shadow: 0 0 5px rgba(255, 0, 102, 0.5);
}

@keyframes requiredPulse {
  0% { transform: scale(1); }
  50% { transform: scale(1.2); }
  100% { transform: scale(1); }
}

/* Textarea per note */
textarea {
  width: 100%;
  padding: 0.75rem;
  border: 3px solid transparent;
  border-radius: 10px;
  font-family: inherit;
  font-size: clamp(0.8rem, 2vw, 0.9rem);
  resize: vertical;
  min-height: clamp(50px, 10vw, 60px);
  transition: all 0.3s ease;
  box-sizing: border-box;
  background: linear-gradient(white, white) padding-box,
              linear-gradient(45deg, #ff0066, #00ffcc, #ffcc00, #66ff00) border-box;
  background-size: 100% 100%, 400% 400%;
  animation: textareaBorder 4s ease infinite;
}

@keyframes textareaBorder {
  0% { background-position: 0% 50%, 0% 50%; }
  50% { background-position: 0% 50%, 100% 50%; }
  100% { background-position: 0% 50%, 0% 50%; }
}

textarea:focus {
  outline: none;
  box-shadow: 0 0 20px rgba(255, 0, 255, 0.5), 0 0 40px rgba(0, 255, 255, 0.3);
  transform: scale(1.02);
}

textarea.error {
  background: linear-gradient(rgba(255, 0, 102, 0.1), rgba(255, 0, 102, 0.1)) padding-box,
              linear-gradient(45deg, #ff0066, #ff6600) border-box;
  animation: textareaError 1s ease infinite;
}

@keyframes textareaError {
  0% { box-shadow: 0 0 10px rgba(255, 0, 102, 0.5); }
  50% { box-shadow: 0 0 20px rgba(255, 0, 102, 0.8); }
  100% { box-shadow: 0 0 10px rgba(255, 0, 102, 0.5); }
}

/* Sistema di rating a stelle */
.star-rating {
  display: flex;
  align-items: center;
  gap: clamp(0.2rem, 1vw, 0.3rem);
  padding: 0.5rem 0;
  flex-wrap: wrap;
  justify-content: flex-start;
}

.star-rating.error {
  background: linear-gradient(45deg, rgba(255, 0, 102, 0.2), rgba(255, 102, 0, 0.2));
  background-size: 400% 400%;
  animation: starError 2s ease infinite;
  border-radius: 10px;
  padding: 0.5rem;
  border: 3px solid #ff0066;
  box-shadow: 0 0 15px rgba(255, 0, 102, 0.4);
}

@keyframes starError {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.star {
  font-size: clamp(1.2rem, 4vw, 1.8rem);
  cursor: pointer;
  transition: all 0.3s ease;
  text-shadow: 0 0 10px rgba(255, 193, 7, 0.6);
  user-select: none;
  line-height: 1;
  touch-action: manipulation;
  animation: starFloat 3s ease infinite;
}

@keyframes starFloat {
  0%, 100% { transform: translateY(0px) rotate(0deg); }
  50% { transform: translateY(-5px) rotate(5deg); }
}

.star:hover {
  transform: scale(1.3) rotate(15deg);
  filter: brightness(1.5) hue-rotate(45deg);
  text-shadow: 0 0 20px rgba(255, 193, 7, 0.8), 0 0 30px rgba(255, 0, 255, 0.6);
}

.star.inactive {
  color: #dee2e6;
  text-shadow: none;
  animation: none;
}

.star.hovered {
  transform: scale(1.4) rotate(20deg);
  filter: brightness(1.8) hue-rotate(90deg);
  text-shadow: 0 0 30px rgba(255, 193, 7, 1), 0 0 40px rgba(255, 0, 255, 0.8);
}

/* Stelle colorate in base al valore con effetti psichedelici */
.star-rating.rating-1 .star:not(.inactive) {
  color: #ff0066;
  animation: starPulse1 1s ease infinite alternate;
}

@keyframes starPulse1 {
  0% { color: #ff0066; text-shadow: 0 0 10px rgba(255, 0, 102, 0.6); }
  100% { color: #ff6600; text-shadow: 0 0 20px rgba(255, 102, 0, 0.8); }
}

.star-rating.rating-2 .star:not(.inactive) {
  color: #ff6600;
  animation: starPulse2 1.5s ease infinite alternate;
}

@keyframes starPulse2 {
  0% { color: #ff6600; text-shadow: 0 0 10px rgba(255, 102, 0, 0.6); }
  100% { color: #ffcc00; text-shadow: 0 0 20px rgba(255, 204, 0, 0.8); }
}

.star-rating.rating-3 .star:not(.inactive),
.star-rating.rating-4 .star:not(.inactive) {
  color: #66ff00;
  animation: starPulse3 2s ease infinite alternate;
}

@keyframes starPulse3 {
  0% { color: #66ff00; text-shadow: 0 0 10px rgba(102, 255, 0, 0.6); }
  100% { color: #00ff66; text-shadow: 0 0 20px rgba(0, 255, 102, 0.8); }
}

/* Testo descrittivo psichedelico */
.rating-description {
  margin-left: clamp(0.5rem, 2vw, 1rem);
  font-size: clamp(0.75rem, 2vw, 0.9rem);
  font-weight: 700;
  padding: 0.5rem 1rem;
  border-radius: 20px;
  border: 2px solid transparent;
  color: white;
  transition: all 0.3s ease;
  white-space: nowrap;
  flex-shrink: 0;
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
  animation: descriptionGlow 2s ease infinite alternate;
}

@keyframes descriptionGlow {
  0% { box-shadow: 0 0 10px rgba(255, 0, 255, 0.3); }
  100% { box-shadow: 0 0 20px rgba(0, 255, 255, 0.5); }
}

.star-rating.rating-1 .rating-description {
  background: linear-gradient(45deg, #ff0066, #ff6600);
  background-size: 400% 400%;
  animation: desc1 2s ease infinite;
}

@keyframes desc1 {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.star-rating.rating-2 .rating-description {
  background: linear-gradient(45deg, #ff6600, #ffcc00);
  background-size: 400% 400%;
  animation: desc2 2s ease infinite;
}

@keyframes desc2 {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.star-rating.rating-3 .rating-description,
.star-rating.rating-4 .rating-description {
  background: linear-gradient(45deg, #66ff00, #00ff66, #00ffcc);
  background-size: 400% 400%;
  animation: desc3 2s ease infinite;
}

@keyframes desc3 {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.error-text {
  color: #ff0066;
  font-size: clamp(0.7rem, 2vw, 0.8rem);
  margin-left: 0.5rem;
  font-weight: 700;
  animation: errorTextPulse 1s ease infinite;
  text-shadow: 0 0 5px rgba(255, 0, 102, 0.5);
}

@keyframes errorTextPulse {
  0% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.7; transform: scale(1.1); }
  100% { opacity: 1; transform: scale(1); }
}

/* Contenitore dei pulsanti */
.button-container {
  display: flex;
  gap: clamp(0.5rem, 2vw, 1rem);
  margin: clamp(0.5rem, 1vw, 0.75rem) clamp(0.5rem, 2vw, 1rem) clamp(0.5rem, 2vw, 1rem);
  flex-wrap: wrap;
  justify-content: center;
  flex-shrink: 0;
  margin-top: auto;
}

/* Pulsante PDF psichedelico */
.button-pdf {
  background: linear-gradient(45deg, #007bff, #0056b3, #6f42c1, #e83e8c, #fd7e14, #20c997);
  background-size: 600% 600%;
  animation: buttonPdf 3s ease infinite;
  color: white;
  border: none;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 2rem);
  font-size: clamp(0.9rem, 2vw, 1.1rem);
  font-weight: 700;
  border-radius: 15px;
  cursor: pointer;
  box-shadow: 0 0 30px rgba(0, 123, 255, 0.5), 0 0 60px rgba(111, 66, 193, 0.3);
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex: 1;
  justify-content: center;
  min-width: clamp(150px, 30vw, 200px);
  touch-action: manipulation;
  text-shadow: 0 0 10px rgba(0, 0, 0, 0.5);
  position: relative;
  overflow: hidden;
}

@keyframes buttonPdf {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}

.button-pdf:hover {
  transform: translateY(-5px) scale(1.05);
  box-shadow: 0 0 40px rgba(0, 123, 255, 0.7), 0 0 80px rgba(111, 66, 193, 0.5);
  filter: brightness(1.2) hue-rotate(45deg);
}

.button-pdf:active {
  transform: translateY(-2px) scale(1.02);
}

/* Pulsante di invio psichedelico */
.button-invia {
  background: linear-gradient(45deg, #28a745, #20c997, #17a2b8, #6f42c1, #e83e8c, #fd7e14);
  background-size: 600% 600%;
  animation: buttonInvia 3s ease infinite;
  color: white;
  border: none;
  padding: clamp(0.75rem, 2vw, 1rem) clamp(1rem, 3vw, 2rem);
  font-size: clamp(0.9rem, 2vw, 1.1rem);
  font-weight: 700;
  border-radius: 15px;
  cursor: pointer;
  box-shadow: 0 0 30px rgba(40, 167, 69, 0.5), 0 0 60px rgba(32, 201, 151, 0.3);
  transition: all 0.3s ease;
  text-transform: uppercase;
  letter-spacing: 1px;
